import React, { useState, useEffect } from 'react';

export default function AdminDashboard() {
  // Admin Profile State
  const [admin, setAdmin] = useState({
    _id: "64a78bc9d1234567890abcde", // Replace with auth context/session ID
    fullName: "admin",
    email: "admin@onlinebus.bd",
    phone: "+880 1700-000000"
  });

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState({ ...admin });

  // Password State
  const [passwordForm, setPasswordForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  // Passengers State
  const [passengers, setPassengers] = useState([
    { _id: "6a773ead78429cd536394ff0", fullName: "abcd", email: "abc@gmail.com", phone: "01784235102341", createdAt: "2026-08-07", status: "Active" },
    { _id: "6a773ead78429cd536394ff1", fullName: "ameen", email: "ameen@gmail.com", phone: "01712345678", createdAt: "2026-08-08", status: "Active" }
  ]);

  // Activity Log Modal State
  const [selectedUserLogs, setSelectedUserLogs] = useState(null);
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);

  // Handle Profile Update
  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:3001/api/admin/profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ adminId: admin._id, ...profileForm })
      });
      const data = await res.json();
      if (res.ok) {
        setAdmin(profileForm);
        setIsEditingProfile(false);
        alert('Profile updated successfully!');
      } else {
        alert(data.error);
      }
    } catch (err) {
      alert('Failed to update profile');
    }
  };

  // Handle Password Change
  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("New passwords do not match!");
      return;
    }
    try {
      const res = await fetch('http://localhost:3001/api/admin/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          adminId: admin._id,
          currentPassword: passwordForm.currentPassword,
          newPassword: passwordForm.newPassword
        })
      });
      const data = await res.json();
      if (res.ok) {
        alert("Password updated successfully!");
        setPasswordForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
      } else {
        alert(data.error);
      }
    } catch (err) {
      alert('Failed to change password');
    }
  };

  // Handle Fetching Activity Log
  const handleViewActivityLog = async (userId, serialNum) => {
    try {
      const res = await fetch(`http://localhost:3001/api/users/${userId}/activity-log`);
      const data = await res.json();
      
      // Fallback dummy logs if backend database has no logs yet
      const logs = data.logs && data.logs.length > 0 ? data.logs : [
        { _id: '1', action: 'Account Created', timestamp: '2026-08-07 10:30 AM', ipAddress: '192.168.1.1' },
        { _id: '2', action: 'Booked Ticket #BUS-8821', timestamp: '2026-08-07 02:15 PM', ipAddress: '192.168.1.1' },
        { _id: '3', action: 'Logged In', timestamp: '2026-08-08 08:45 AM', ipAddress: '103.204.2.10' }
      ];

      setSelectedUserLogs({
        serialId: `#${serialNum}`,
        dbId: userId,
        userName: data.user ? data.user.fullName : passengers.find(p => p._id === userId)?.fullName,
        logs: logs
      });
      setIsLogModalOpen(true);
    } catch (err) {
      alert("Failed to fetch activity logs");
    }
  };

  return (
    <div style={{ backgroundColor: '#121316', color: '#fff', minHeight: '100vh', padding: '24px', fontFamily: 'sans-serif' }}>
      
      {/* 1. ADMINISTRATOR PROFILE SECTION */}
      <div style={{ backgroundColor: '#1a1c20', borderRadius: '12px', padding: '24px', marginBottom: '24px', border: '1px solid #2a2d34' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <div>
            <h2 style={{ margin: 0, fontSize: '20px' }}>Administrator Profile</h2>
            <p style={{ margin: '4px 0 0 0', color: '#8b8d97', fontSize: '14px' }}>Manage system administrative details and system privileges</p>
          </div>
          <div>
            <span style={{ backgroundColor: '#133929', color: '#25c974', padding: '6px 12px', borderRadius: '20px', fontSize: '13px', marginRight: '10px' }}>✓ System Active</span>
            <button 
              onClick={() => setIsEditingProfile(!isEditingProfile)} 
              style={{ backgroundColor: '#2a2d34', color: '#fff', border: '1px solid #3a3d46', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }}
            >
              ✏️ {isEditingProfile ? 'Cancel Edit' : 'Edit Info'}
            </button>
          </div>
        </div>

        {isEditingProfile ? (
          <form onSubmit={handleProfileSubmit} style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>Full Name</label>
              <input 
                type="text" 
                value={profileForm.fullName} 
                onChange={(e) => setProfileForm({ ...profileForm, fullName: e.target.value })}
                style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>Email Address</label>
              <input 
                type="email" 
                value={profileForm.email} 
                onChange={(e) => setProfileForm({ ...profileForm, email: e.target.value })}
                style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>Phone Contact</label>
              <input 
                type="text" 
                value={profileForm.phone} 
                onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })}
                style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
              />
            </div>
            <button type="submit" style={{ gridColumn: 'span 3', backgroundColor: '#e65100', color: '#fff', border: 'none', padding: '10px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>
              Save Profile Changes
            </button>
          </form>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: '150px repeat(3, 1fr)', gap: '16px', alignItems: 'center' }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ width: '80px', height: '80px', borderRadius: '50%', backgroundColor: '#2a2d34', margin: '0 auto', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '32px' }}>👤</div>
              <span style={{ fontSize: '11px', color: '#8b8d97' }}>Allowed JPG, PNG</span>
            </div>
            <div style={{ backgroundColor: '#121316', padding: '16px', borderRadius: '8px' }}>
              <span style={{ fontSize: '12px', color: '#8b8d97' }}>👤 Full Name</span>
              <div style={{ fontWeight: 'bold', marginTop: '4px' }}>{admin.fullName}</div>
            </div>
            <div style={{ backgroundColor: '#121316', padding: '16px', borderRadius: '8px' }}>
              <span style={{ fontSize: '12px', color: '#8b8d97' }}>✉️ Email Address</span>
              <div style={{ fontWeight: 'bold', marginTop: '4px' }}>{admin.email}</div>
            </div>
            <div style={{ backgroundColor: '#121316', padding: '16px', borderRadius: '8px' }}>
              <span style={{ fontSize: '12px', color: '#8b8d97' }}>📞 Phone Contact</span>
              <div style={{ fontWeight: 'bold', marginTop: '4px' }}>{admin.phone}</div>
            </div>
          </div>
        )}
      </div>

      {/* 2. REGISTERED PASSENGERS SECTION WITH SERIAL USERS */}
      <div style={{ backgroundColor: '#1a1c20', borderRadius: '12px', padding: '24px', marginBottom: '24px', border: '1px solid #2a2d34' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <div>
            <h2 style={{ margin: 0, fontSize: '20px' }}>Registered Passengers</h2>
            <p style={{ margin: '4px 0 0 0', color: '#8b8d97', fontSize: '14px' }}>Live user database synchronized across system terminals</p>
          </div>
          <div>
            <span style={{ backgroundColor: '#2a2d34', padding: '6px 12px', borderRadius: '6px', fontSize: '13px', marginRight: '10px' }}>{passengers.length} Active Accounts</span>
            <button style={{ backgroundColor: '#2a2d34', color: '#fff', border: '1px solid #3a3d46', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }}>📥 Export CSV</button>
          </div>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '14px' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #2a2d34', color: '#8b8d97' }}>
              <th style={{ padding: '12px' }}>SERIAL ID</th>
              <th style={{ padding: '12px' }}>PASSENGER</th>
              <th style={{ padding: '12px' }}>EMAIL / ACCOUNT</th>
              <th style={{ padding: '12px' }}>PHONE</th>
              <th style={{ padding: '12px' }}>JOINED</th>
              <th style={{ padding: '12px' }}>STATUS</th>
              <th style={{ padding: '12px' }}>ACTIONS</th>
            </tr>
          </thead>
          <tbody>
            {passengers.map((p, index) => (
              <tr key={p._id} style={{ borderBottom: '1px solid #2a2d34' }}>
                {/* USER ID IN SERIAL ORDER (1, 2, 3...) */}
                <td style={{ padding: '12px' }}>
                  <span style={{ backgroundColor: '#2a1a15', color: '#ff6b35', padding: '4px 8px', borderRadius: '4px', fontWeight: 'bold' }}>
                    #{index + 1}
                  </span>
                </td>
                <td style={{ padding: '12px', fontWeight: 'bold' }}>{p.fullName}</td>
                <td style={{ padding: '12px', color: '#8b8d97' }}>{p.email}</td>
                <td style={{ padding: '12px' }}>{p.phone}</td>
                <td style={{ padding: '12px', color: '#8b8d97' }}>{p.createdAt}</td>
                <td style={{ padding: '12px' }}>
                  <span style={{ backgroundColor: '#133929', color: '#25c974', padding: '4px 8px', borderRadius: '4px', fontSize: '12px' }}>{p.status}</span>
                </td>
                <td style={{ padding: '12px' }}>
                  <button 
                    onClick={() => handleViewActivityLog(p._id, index + 1)}
                    style={{ backgroundColor: '#2a2d34', color: '#fff', border: '1px solid #3a3d46', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontSize: '12px' }}
                  >
                    ⏱ Activity Log
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 3. SECURITY & CREDENTIALS (CHANGE PASSWORD) */}
      <div style={{ backgroundColor: '#1a1c20', borderRadius: '12px', padding: '24px', border: '1px solid #2a2d34' }}>
        <h2 style={{ margin: 0, fontSize: '20px' }}>Security & Credentials</h2>
        <p style={{ margin: '4px 0 20px 0', color: '#8b8d97', fontSize: '14px' }}>Update account password and security preferences</p>

        <form onSubmit={handlePasswordSubmit} style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px' }}>
          <div>
            <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>Current Password</label>
            <input 
              type="password" 
              required
              value={passwordForm.currentPassword}
              onChange={(e) => setPasswordForm({ ...passwordForm, currentPassword: e.target.value })}
              style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
            />
          </div>
          <div>
            <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>New Password</label>
            <input 
              type="password" 
              required
              value={passwordForm.newPassword}
              onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
              style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
            />
          </div>
          <div>
            <label style={{ display: 'block', fontSize: '12px', color: '#8b8d97', marginBottom: '4px' }}>Confirm New Password</label>
            <input 
              type="password" 
              required
              value={passwordForm.confirmPassword}
              onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
              style={{ width: '100%', padding: '10px', borderRadius: '6px', backgroundColor: '#121316', border: '1px solid #3a3d46', color: '#fff' }} 
            />
          </div>
          <button type="submit" style={{ gridColumn: 'span 1', backgroundColor: '#e65100', color: '#fff', border: 'none', padding: '10px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>
            Update Password
          </button>
        </form>
      </div>

      {/* 4. USER ACTIVITY LOG MODAL */}
      {isLogModalOpen && selectedUserLogs && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.8)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: '#1a1c20', width: '500px', borderRadius: '12px', padding: '24px', border: '1px solid #3a3d46' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #2a2d34', paddingBottom: '12px' }}>
              <div>
                <h3 style={{ margin: 0 }}>Activity Log: {selectedUserLogs.userName}</h3>
                <span style={{ fontSize: '12px', color: '#ff6b35' }}>Serial ID: {selectedUserLogs.serialId} | Database Mongo ID: {selectedUserLogs.dbId}</span>
              </div>
              <button onClick={() => setIsLogModalOpen(false)} style={{ background: 'none', border: 'none', color: '#fff', cursor: 'pointer', fontSize: '18px' }}>✕</button>
            </div>

            <div style={{ marginTop: '16px', maxHeight: '300px', overflowY: 'auto' }}>
              {selectedUserLogs.logs.map((log) => (
                <div key={log._id} style={{ backgroundColor: '#121316', padding: '12px', borderRadius: '6px', marginBottom: '8px', borderLeft: '3px solid #e65100' }}>
                  <div style={{ fontWeight: 'bold', fontSize: '14px' }}>{log.action}</div>
                  <div style={{ fontSize: '12px', color: '#8b8d97', marginTop: '4px', display: 'flex', justifyContent: 'space-between' }}>
                    <span>📅 {log.timestamp}</span>
                    <span>🌐 IP: {log.ipAddress}</span>
                  </div>
                </div>
              ))}
            </div>

            <button 
              onClick={() => setIsLogModalOpen(false)}
              style={{ width: '100%', marginTop: '16px', padding: '10px', backgroundColor: '#2a2d34', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
            >
              Close History
            </button>
          </div>
        </div>
      )}

    </div>
  );
}
